#!/usr/bin/env bash
# Generates src/error-codes.ts from src/Common/ErrorCodes.cpp of an upstream
# ClickHouse checkout. The shim maps the error names of test hints
# (`-- { serverError SYNTAX_ERROR }`) to their codes with it, as
# clickhouse-client does. fetch-upstream.sh runs this script; commit the
# generated file when it changes.
#
# Usage: scripts/gen-error-codes.sh <upstream ClickHouse checkout>
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
RUNNER_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
src="${1:?usage: gen-error-codes.sh <upstream ClickHouse checkout>}/src/Common/ErrorCodes.cpp"
out="${RUNNER_DIR}/src/error-codes.ts"

if [[ ! -f "${src}" ]]; then
  echo "Error: ${src} not found." >&2
  exit 1
fi
ref="$(cat "$(dirname "${src}")/../../.upstream-ref" 2> /dev/null || echo unknown)"

{
  echo "// Generated by scripts/gen-error-codes.sh from src/Common/ErrorCodes.cpp"
  echo "// of ClickHouse ${ref}. Do not edit."
  echo ""
  echo "/** Error name -> error code, as in src/Common/ErrorCodes.cpp. */"
  echo "export const ERROR_CODES: ReadonlyMap<string, number> = new Map<string, number>(["
  # Each code is a line `M(62, SYNTAX_ERROR) \` of the APPLY_FOR_ERROR_CODES list.
  sed -nE 's/^[[:space:]]*M\(([0-9]+),[[:space:]]*([A-Z0-9_]+)\).*/  ["\2", \1],/p' "${src}"
  echo "]);"
} > "${out}"

count="$(grep -c '^  \["' "${out}")"
if ((count < 100)); then
  echo "Error: only ${count} error codes found in ${src}; the format of the file changed." >&2
  exit 1
fi
echo "Wrote ${count} error codes to ${out}" >&2
